"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[22012],{88378(e,a,o){o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/docker/modulos/buenas-practicas-patrones/cuestionario","title":"Cuestionario M24 \u2014 Buenas Pr\xe1cticas y Patrones Docker","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/24-buenas-practicas-patrones/cuestionario.md","sourceDirName":"cursos/docker/modulos/24-buenas-practicas-patrones","slug":"/cursos/docker/modulos/buenas-practicas-patrones/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/buenas-practicas-patrones/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/buenas-practicas-patrones/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/buenas-practicas-patrones/ejercicio"}}');var n=o(74848),r=o(28453);const i={sidebar_label:"Cuestionario"},c="Cuestionario M24 \u2014 Buenas Pr\xe1cticas y Patrones Docker",t={},l=[{value:"1. [Investigar] \xbfQu\xe9 es exactamente Dapr (Distributed Application Runtime) y c\xf3mo implementa patrones de microservicios (state management, pub/sub, actor model) sin acoplar la aplicaci\xf3n a SDKs espec\xedficos?",id:"1-investigar-qu\xe9-es-exactamente-dapr-distributed-application-runtime-y-c\xf3mo-implementa-patrones-de-microservicios-state-management-pubsub-actor-model-sin-acoplar-la-aplicaci\xf3n-a-sdks-espec\xedficos",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente &quot;Chaos Engineering&quot; en el contexto de contenedores y c\xf3mo herramientas como LitmusChaos o Chaos Mesh implementan experimentos?",id:"2-investigar-qu\xe9-es-exactamente-chaos-engineering-en-el-contexto-de-contenedores-y-c\xf3mo-herramientas-como-litmuschaos-o-chaos-mesh-implementan-experimentos",level:3},{value:"3. [Investigar] \xbfQu\xe9 son exactamente los &quot;SLIs, SLOs, y SLAs&quot; y c\xf3mo se aplican a aplicaciones containerizadas? \xbfC\xf3mo se relacionan con los healthchecks y el monitoreo?",id:"3-investigar-qu\xe9-son-exactamente-los-slis-slos-y-slas-y-c\xf3mo-se-aplican-a-aplicaciones-containerizadas-c\xf3mo-se-relacionan-con-los-healthchecks-y-el-monitoreo",level:3},{value:"4. [Investigar] \xbfQu\xe9 es exactamente &quot;Crossplane&quot; y c\xf3mo implementa &quot;Infrastructure as Code&quot; usando Kubernetes como plano de control? \xbfEn qu\xe9 se diferencia de Terraform?",id:"4-investigar-qu\xe9-es-exactamente-crossplane-y-c\xf3mo-implementa-infrastructure-as-code-usando-kubernetes-como-plano-de-control-en-qu\xe9-se-diferencia-de-terraform",level:3},{value:"5. [Conectar] La clase menciona 12 Factor App. \xbfC\xf3mo se relaciona este manifiesto con el &quot;Beyond the 12 Factor App&quot; (Kevin Hoffman, 2016) y qu\xe9 factores adicionales propone para la era de contenedores?",id:"5-conectar-la-clase-menciona-12-factor-app-c\xf3mo-se-relaciona-este-manifiesto-con-el-beyond-the-12-factor-app-kevin-hoffman-2016-y-qu\xe9-factores-adicionales-propone-para-la-era-de-contenedores",level:3},{value:"6. [Conectar] La clase menciona Sidecar, Ambassador, y Adapter. \xbfC\xf3mo se implementan estos patrones en Kubernetes con Pods multi-contenedor y c\xf3mo se relacionan con Init Containers?",id:"6-conectar-la-clase-menciona-sidecar-ambassador-y-adapter-c\xf3mo-se-implementan-estos-patrones-en-kubernetes-con-pods-multi-contenedor-y-c\xf3mo-se-relacionan-con-init-containers",level:3},{value:"7. [Conectar] \xbfC\xf3mo funciona el &quot;graceful shutdown&quot; con <code>PreStop</code> hook y SIGTERM en K8s? \xbfQu\xe9 diferencia hay con <code>docker stop</code> y c\xf3mo implementar shutdown ordenado?",id:"7-conectar-c\xf3mo-funciona-el-graceful-shutdown-con-prestop-hook-y-sigterm-en-k8s-qu\xe9-diferencia-hay-con-docker-stop-y-c\xf3mo-implementar-shutdown-ordenado",level:3},{value:"8. [Cuestionar] \xbfSon los patrones Sidecar/Ambassador/Adapter una buena pr\xe1ctica o introducen complejidad innecesaria? \xbfCu\xe1ndo es mejor modificar la aplicaci\xf3n en lugar de agregar sidecars?",id:"8-cuestionar-son-los-patrones-sidecarambassadoradapter-una-buena-pr\xe1ctica-o-introducen-complejidad-innecesaria-cu\xe1ndo-es-mejor-modificar-la-aplicaci\xf3n-en-lugar-de-agregar-sidecars",level:3},{value:"9. [Cuestionar] \xbfDeben las aplicaciones implementar &quot;retry logic&quot; y &quot;circuit breakers&quot; o debe hacerlo la plataforma (Service Mesh, Dapr, API Gateway)?",id:"9-cuestionar-deben-las-aplicaciones-implementar-retry-logic-y-circuit-breakers-o-debe-hacerlo-la-plataforma-service-mesh-dapr-api-gateway",level:3},{value:"10. [Cuestionar] \xbfEs el &quot;12 Factor App&quot; todav\xeda relevante en 2025 o necesita una actualizaci\xf3n significativa para la era de serverless, WebAssembly, y edge computing?",id:"10-cuestionar-es-el-12-factor-app-todav\xeda-relevante-en-2025-o-necesita-una-actualizaci\xf3n-significativa-para-la-era-de-serverless-webassembly-y-edge-computing",level:3}];function d(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"cuestionario-m24--buenas-pr\xe1cticas-y-patrones-docker",children:"Cuestionario M24 \u2014 Buenas Pr\xe1cticas y Patrones Docker"})}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,n.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"1-investigar-qu\xe9-es-exactamente-dapr-distributed-application-runtime-y-c\xf3mo-implementa-patrones-de-microservicios-state-management-pubsub-actor-model-sin-acoplar-la-aplicaci\xf3n-a-sdks-espec\xedficos",children:"1. [Investigar] \xbfQu\xe9 es exactamente Dapr (Distributed Application Runtime) y c\xf3mo implementa patrones de microservicios (state management, pub/sub, actor model) sin acoplar la aplicaci\xf3n a SDKs espec\xedficos?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Dapr (Microsoft, proyecto CNCF incubado) es un runtime portable que se ejecuta como sidecar (o en modo ambient) y provee APIs HTTP/gRPC para patrones de microservicios: 1) ",(0,n.jsx)(a.strong,{children:"Service invocation"}),": llamada entre servicios con mTLS, retries, circuit breaking, y service discovery (sin que la app sepa la ubicaci\xf3n de otros servicios), 2) ",(0,n.jsx)(a.strong,{children:"State management"}),": CRUD en almacenes clave-valor (Redis, PostgreSQL, CosmosDB) con consistencia configurable, 3) ",(0,n.jsx)(a.strong,{children:"Pub/sub"}),": mensajer\xeda publish/subscribe (Kafka, RabbitMQ, Azure Service Bus) con dead letter, retries, y garant\xedas de delivery, 4) ",(0,n.jsx)(a.strong,{children:"Bindings"}),": triggers de entrada/salida para integraciones externas (blob storage, cron, SMTP), 5) ",(0,n.jsx)(a.strong,{children:"Actors"}),": virtual actor pattern para stateful concurrency, 6) ",(0,n.jsx)(a.strong,{children:"Secrets"}),": acceso a secretos de m\xfaltiples providers (Vault, K8s Secrets, AWS Secrets Manager). La app habla con Dapr via ",(0,n.jsx)(a.code,{children:"localhost:3500"})," (HTTP) o ",(0,n.jsx)(a.code,{children:"localhost:50001"})," (gRPC), sin SDK (aunque hay SDKs opcionales para simplificar). Esto desacopla la aplicaci\xf3n de la infraestructura: si cambi\xe1s de Redis a PostgreSQL para state, la app no cambia."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Dapr fue creado por Yaron Schneider, Mark Fussell, y el equipo de Azure (2019). Se inspira en los sidecar patterns (como Envoy) pero para l\xf3gica de aplicaci\xf3n, no solo networking. La filosof\xeda: "Cualquier lenguaje, cualquier cloud, cualquier infraestructura". Los building blocks de Dapr (state, pub/sub, actors) encapsulan patrones que de otra forma tendr\xedas que implementar con librer\xedas espec\xedficas (ej. ',(0,n.jsx)(a.code,{children:"redis-py"})," o ",(0,n.jsx)(a.code,{children:"confluent-kafka-python"}),") acoplando la app a la tecnolog\xeda."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-exactamente-chaos-engineering-en-el-contexto-de-contenedores-y-c\xf3mo-herramientas-como-litmuschaos-o-chaos-mesh-implementan-experimentos",children:'2. [Investigar] \xbfQu\xe9 es exactamente "Chaos Engineering" en el contexto de contenedores y c\xf3mo herramientas como LitmusChaos o Chaos Mesh implementan experimentos?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Chaos Engineering (Netflix, "Chaos Monkey", 2010; Casey Rosenthal, Nora Jones) es la pr\xe1ctica de experimentar en sistemas en producci\xf3n para descubrir debilidades antes de que causen outages. En contenedores, herramientas como LitmusChaos (CNCF incubado) y Chaos Mesh (CNCF incubado) implementan experimentos como CRDs de K8s: 1) ',(0,n.jsx)(a.strong,{children:"Pod kill"}),": mata Pods aleatorios y verifica que el sistema sigue funcionando (replicas, auto-scaling), 2) ",(0,n.jsx)(a.strong,{children:"Network chaos"}),": introduce latencia, packet loss, o particiones de red entre servicios para probar timeouts y circuit breakers, 3) ",(0,n.jsx)(a.strong,{children:"Stress chaos"}),": consume CPU/memoria de Pods para simular picos de carga y verificar eviction policies, 4) ",(0,n.jsx)(a.strong,{children:"IO chaos"}),": introduce latencia/errores en I/O (filesystem, disco) para probar comportamiento bajo storage degradation, 5) ",(0,n.jsx)(a.strong,{children:"Time chaos"}),": manipula el reloj del sistema para probar comportamiento con time skew. Los experimentos se definen como YAML de K8s (declarativos), se ejecutan con hypotheses (estado esperado), y se miden con m\xe9tricas de Prometheus/Grafana."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Netflix populariz\xf3 Chaos Engineering con Chaos Monkey (2010), pero el ecosistema cloud-native ahora tiene herramientas nativas de K8s. LitmusChaos (MayaData, 2019) y Chaos Mesh (PingCAP, 2019) son las m\xe1s populares. La pr\xe1ctica: ejecutar experimentos CA\xd3TICOS primero en staging, luego en producci\xf3n en ventanas controladas, midiendo el "blast radius" y verificando que el sistema degrada gracefully (no catastr\xf3ficamente).']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-qu\xe9-son-exactamente-los-slis-slos-y-slas-y-c\xf3mo-se-aplican-a-aplicaciones-containerizadas-c\xf3mo-se-relacionan-con-los-healthchecks-y-el-monitoreo",children:'3. [Investigar] \xbfQu\xe9 son exactamente los "SLIs, SLOs, y SLAs" y c\xf3mo se aplican a aplicaciones containerizadas? \xbfC\xf3mo se relacionan con los healthchecks y el monitoreo?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': SLI (Service Level Indicator): m\xe9trica cuantificable del servicio (ej. latencia p99 de requests, porcentaje de requests exitosos). SLO (Service Level Objective): objetivo para un SLI en un per\xedodo (ej. "99.9% de requests exitosos en los \xfaltimos 30 d\xedas"). SLA (Service Level Agreement): contrato con el cliente con consecuencias si no se cumple (ej. "si availability <99.5%, cr\xe9dito por outage"). En aplicaciones containerizadas: 1) Los healthchecks de Docker/K8s b\xe1sicamente miden si el contenedor est\xe1 "vivo" (SLI binario), pero no miden SLOs (calidad de servicio), 2) Para SLOs, necesit\xe1s m\xe9tricas de aplicaci\xf3n: latencia, error rate, throughput \u2014 colectadas con Prometheus + OpenTelemetry, 3) SLOs gu\xedan la arquitectura: si tu SLO es 99.9% availability, necesit\xe1s al menos 2 r\xe9plicas + rolling updates + healthchecks + auto-scaling, 4) Error budgets: 1 - SLO = cu\xe1nto downtime "permitido" (ej. 99.9% = 43 minutos/mes). Esto gu\xeda decisiones: \xbfpodemos hacer un deploy riesgoso? Si el error budget est\xe1 quemado, no.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Los conceptos de SLI/SLO/SLA fueron popularizados por el libro "Site Reliability Engineering" (Google, 2016, editado por Betsy Beyer, Chris Jones, Niall Murphy). Para contenedores, el monitoreo de SLOs es m\xe1s importante que solo monitorear "\xbfest\xe1 el contenedor corriendo?" porque un contenedor healthy puede estar sirviendo errores 500. Herramientas como Sloth, Pyrra, y Google\'s SLOtter automatizan el tracking de SLOs y error budgets desde Prometheus.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-exactamente-crossplane-y-c\xf3mo-implementa-infrastructure-as-code-usando-kubernetes-como-plano-de-control-en-qu\xe9-se-diferencia-de-terraform",children:'4. [Investigar] \xbfQu\xe9 es exactamente "Crossplane" y c\xf3mo implementa "Infrastructure as Code" usando Kubernetes como plano de control? \xbfEn qu\xe9 se diferencia de Terraform?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Crossplane (Upbound, proyecto CNCF incubado) extiende K8s con CRDs que representan recursos cloud (EC2, RDS, GKE, etc.). Los recursos cloud se definen como YAML (K8s-style) y Crossplane los crea/gestiona en el cloud provider usando controladores (providers: AWS, Azure, GCP). Diferencias con Terraform: 1) Terraform es un CLI imperativo (",(0,n.jsx)(a.code,{children:"terraform apply"}),') con state file centralizado. Crossplane es un controlador K8s declarativo (reconciliation loop continuo \u2014 si alguien borra el RDS manualmente, Crossplane lo recrea), 2) Terraform usa HCL (lenguaje propio). Crossplane usa YAML de K8s (compatible con GitOps: ArgoCD/Flux), 3) Crossplane implementa "Composite Resources" (abstracciones): un equipo de plataforma define un ',(0,n.jsx)(a.code,{children:"CompositeResourceDefinition"}),' como "PostgreSQL-as-a-Service" (con tama\xf1o, HA, backup), y los devs crean un claim de ese recurso sin conocer los detalles de RDS/GCP. Terraform no tiene este concepto de "platform engineering API".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Crossplane fue creado por Bassam Tabbara y Jared Watts (ex-Microsoft Azure) en 2019. La filosof\xeda: "Kubernetes as the universal control plane". No reemplaza Terraform: se complementan. Terraform es mejor para provisionar el cluster K8s mismo (y otros recursos no-K8s). Crossplane es mejor para gestionar recursos cloud DESDE K8s (para equipos que ya usan K8s y quieren GitOps). La tendencia: Terraform para crear el cluster, Crossplane para lo que corre dentro/relacionado al cluster.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-12-factor-app-c\xf3mo-se-relaciona-este-manifiesto-con-el-beyond-the-12-factor-app-kevin-hoffman-2016-y-qu\xe9-factores-adicionales-propone-para-la-era-de-contenedores",children:'5. [Conectar] La clase menciona 12 Factor App. \xbfC\xf3mo se relaciona este manifiesto con el "Beyond the 12 Factor App" (Kevin Hoffman, 2016) y qu\xe9 factores adicionales propone para la era de contenedores?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': "Beyond the 12 Factor App" (Kevin Hoffman, 2016, Pivotal) propone 3 factores adicionales para la era cloud-native: 13) ',(0,n.jsx)(a.strong,{children:"API First"}),": dise\xf1ar APIs antes que UIs. En contenedores: exponer endpoints REST/gRPC, documentar con OpenAPI, usar API gateways, 14) ",(0,n.jsx)(a.strong,{children:"Telemetry"}),": observabilidad desde el inicio. En contenedores: m\xe9tricas (Prometheus), logs estructurados, traces distribuidas (OpenTelemetry) \u2014 no es opcional, es fundamental para debugging en producci\xf3n, 15) ",(0,n.jsx)(a.strong,{children:"Authentication and Authorization"}),': seguridad desde el dise\xf1o. En contenedores: mTLS entre servicios, identidades SPIFFE, OAuth2/OIDC, y pol\xedticas de acceso por servicio. Adem\xe1s, el libro "Cloud Native Patterns" (Cornelia Davis, 2019) y "Kubernetes Patterns" (Bilgin Ibryam, Roland Hu\xdf, 2019) extienden los 12 factores con patrones espec\xedficos de K8s: Health Checks (liveness/readiness), Lifecycle hooks (PostStart/PreStop), Managed Lifecycle, y Automated Placement.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Los 12 factores originales (Adam Wiggins, 2012, Heroku) fueron visionarios pero no cubr\xedan observabilidad y seguridad (que no eran prioritarias en 2012). "Beyond the 12 Factor App" y "Kubernetes Patterns" llenan esos vac\xedos para la era cloud-native. La comunidad de CNCF tambi\xe9n public\xf3 "Cloud Native Principles" que extienden los 12 factores.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"6-conectar-la-clase-menciona-sidecar-ambassador-y-adapter-c\xf3mo-se-implementan-estos-patrones-en-kubernetes-con-pods-multi-contenedor-y-c\xf3mo-se-relacionan-con-init-containers",children:"6. [Conectar] La clase menciona Sidecar, Ambassador, y Adapter. \xbfC\xf3mo se implementan estos patrones en Kubernetes con Pods multi-contenedor y c\xf3mo se relacionan con Init Containers?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": En K8s: 1) ",(0,n.jsx)(a.strong,{children:"Sidecar"}),": definido como un contenedor adicional en el Pod (",(0,n.jsx)(a.code,{children:"containers[1]"}),"). Comparte network, IPC, y vol\xfamenes con el contenedor principal. Se ejecuta durante toda la vida del Pod (no termina hasta que el Pod muere). Ejemplos: proxy Envoy, config-reloader. 2) ",(0,n.jsx)(a.strong,{children:"Init Container"}),": definido en ",(0,n.jsx)(a.code,{children:"initContainers"}),". Se ejecuta ANTES que los contenedores principales, y DEBE terminarse exitosamente (exit 0) para que los contenedores principales arranquen. Se usa para: inicializar datos (ej. clonar un repo git), esperar dependencias (ej. ",(0,n.jsx)(a.code,{children:"until pg_isready"}),'), o configurar permisos. 3) La diferencia: Sidecar convive con el contenedor principal (runtime concern). Init Container se ejecuta antes y termina (startup concern). K8s 1.29 (2024) introdujo "sidecar containers" como feature estable con ',(0,n.jsx)(a.code,{children:"restartPolicy: Always"})," en init containers (permitiendo que inicien antes que el main container y se reinicien si fallan)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": K8s 1.29 (diciembre 2024) formaliz\xf3 el concepto de sidecar en la API: ",(0,n.jsx)(a.code,{children:"initContainers[].restartPolicy: Always"})," hace que el init container act\xfae como sidecar (se inicia antes que los main containers y persiste durante la vida del Pod). Esto resuelve el problema de orden de inicio (el sidecar debe arrancar antes que la app, pero antes los init containers solo pod\xedan terminar, no persistir). Para Ambassador y Adapter en K8s: conceptualmente, ambos son sidecars (contenedores adicionales en el Pod). La diferencia es su funci\xf3n (proxy vs normalizaci\xf3n), pero en la API de K8s son id\xe9nticos (contenedores en el Pod)."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsxs)(a.h3,{id:"7-conectar-c\xf3mo-funciona-el-graceful-shutdown-con-prestop-hook-y-sigterm-en-k8s-qu\xe9-diferencia-hay-con-docker-stop-y-c\xf3mo-implementar-shutdown-ordenado",children:['7. [Conectar] \xbfC\xf3mo funciona el "graceful shutdown" con ',(0,n.jsx)(a.code,{children:"PreStop"})," hook y SIGTERM en K8s? \xbfQu\xe9 diferencia hay con ",(0,n.jsx)(a.code,{children:"docker stop"})," y c\xf3mo implementar shutdown ordenado?"]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": En K8s, el ciclo de terminaci\xf3n de un Pod: 1) K8s marca el Pod como Terminating (removido de endpoints del Service), 2) K8s ejecuta el ",(0,n.jsx)(a.code,{children:"PreStop"})," hook (si est\xe1 definido). Puede ser un comando (",(0,n.jsx)(a.code,{children:"exec"}),") o un HTTP GET. 3) K8s espera ",(0,n.jsx)(a.code,{children:"terminationGracePeriodSeconds"})," (default 30s). 4) K8s env\xeda SIGTERM al proceso principal del contenedor. 5) Si el proceso no termina en el tiempo restante, K8s env\xeda SIGKILL. Diferencia con ",(0,n.jsx)(a.code,{children:"docker stop"}),": K8s agrega el paso ",(0,n.jsx)(a.code,{children:"PreStop"})," ANTES de SIGTERM, y tiene un grace period \xfanico para todo el Pod. Para implementar shutdown ordenado: 1) Definir ",(0,n.jsx)(a.code,{children:"PreStop"})," hook: ",(0,n.jsx)(a.code,{children:'exec: &#x7B;command: ["/bin/sh", "-c", "sleep 5"]&#x7D;'})," \u2014 espera 5s para que el tr\xe1fico en vuelo se complete (el Pod ya fue removido del Service), 2) La aplicaci\xf3n captura SIGTERM y hace graceful shutdown (dejar de aceptar conexiones, completar requests, cerrar BD), 3) Si el graceful shutdown de la app tarda m\xe1s que el grace period - PreStop time, la app recibe SIGKILL (shutdown forzado)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de K8s (Pod Lifecycle) detalla este proceso. El ",(0,n.jsx)(a.code,{children:"PreStop"})," hook es cr\xedtico para aplicaciones que necesitan drenar tr\xe1fico antes de shutdown (ej. desregistrar de un service discovery, completar requests en cola). El ",(0,n.jsx)(a.code,{children:"sleep 5"})," es un hack com\xfan para dar tiempo a que kube-proxy actualice iptables y deje de enviar tr\xe1fico al Pod (puede haber un delay de 1-2s)."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"8-cuestionar-son-los-patrones-sidecarambassadoradapter-una-buena-pr\xe1ctica-o-introducen-complejidad-innecesaria-cu\xe1ndo-es-mejor-modificar-la-aplicaci\xf3n-en-lugar-de-agregar-sidecars",children:"8. [Cuestionar] \xbfSon los patrones Sidecar/Ambassador/Adapter una buena pr\xe1ctica o introducen complejidad innecesaria? \xbfCu\xe1ndo es mejor modificar la aplicaci\xf3n en lugar de agregar sidecars?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Sidecars son una buena pr\xe1ctica cuando: 1) Quer\xe9s separar concerns (networking vs l\xf3gica de negocio) y que el desarrollador de app no tenga que implementar mTLS, retries, o telemetr\xeda en el c\xf3digo, 2) Necesit\xe1s inyectar funcionalidad transversal a m\xfaltiples aplicaciones (logging, proxy, security) sin tocarlas, 3) La funcionalidad sidecar es standard (Envoy proxy) y es mantenida por un equipo especializado (plataforma/SRE). Es mejor modificar la aplicaci\xf3n cuando: 1) La funcionalidad sidecar introduce demasiado overhead (latencia adicional, consumo de recursos para un proxy extra por Pod), 2) El equipo es peque\xf1o y mantener sidecars operacionalmente es m\xe1s costoso que agregar una librer\xeda al c\xf3digo, 3) Necesit\xe1s l\xf3gica espec\xedfica que un sidecar gen\xe9rico no puede implementar. La tendencia: Service Mesh (sidecars) est\xe1 siendo cuestionado por su complejidad operativa, y alternativas como "ambient mesh" y eBPF (Cilium) buscan reducir/eliminar sidecars. La decisi\xf3n es trade-off: desacoplamiento (sidecars) vs simplicidad operativa (c\xf3digo en la app).']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': El debate sidecar vs no-sidecar se intensific\xf3 en 2023-2024 con la introducci\xf3n de Istio Ambient y Cilium eBPF. William Morgan (Linkerd) defiende sidecars por desacoplamiento. Thomas Graf (Cilium) defiende eBPF por simplicidad y rendimiento. Para la mayor\xeda de equipos, un sidecar de logging (Fluent Bit) o de config reload (configmap-reload) es "gratis" y valioso. Un sidecar de service mesh (Envoy) completo puede ser overkill para equipos peque\xf1os.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"9-cuestionar-deben-las-aplicaciones-implementar-retry-logic-y-circuit-breakers-o-debe-hacerlo-la-plataforma-service-mesh-dapr-api-gateway",children:'9. [Cuestionar] \xbfDeben las aplicaciones implementar "retry logic" y "circuit breakers" o debe hacerlo la plataforma (Service Mesh, Dapr, API Gateway)?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Idealmente, la plataforma (Service Mesh, Dapr, API Gateway) debe manejar retries, circuit breaking, y timeouts porque: 1) Desacopla la l\xf3gica de resiliencia de la l\xf3gica de negocio (desarrollador de app no tiene que escribir ",(0,n.jsx)(a.code,{children:"for retry &#x7B; ... &#x7D;"})," en cada llamada HTTP), 2) La pol\xedtica puede configurarse centralizadamente (cambiar timeout de 5s a 3s sin re-deploy de la app), 3) Las m\xe9tricas de resiliencia (cu\xe1ntos retries, cu\xe1ntos circuit breaks) se colectan sin instrumentaci\xf3n. PERO la aplicaci\xf3n debe implementar: 1) Idempotencia (para que los retries no causen doble procesamiento), 2) Reconocimiento de errores fatales (no retry si el error es 400 Bad Request, s\xed retry si es 503 Service Unavailable), 3) Backpressure awareness (si el circuit breaker est\xe1 abierto, la app debe hacer fall-fast, no esperar). La combinaci\xf3n: plataforma maneja el mecanismo (retry/circuit breaker), aplicaci\xf3n maneja la sem\xe1ntica (idempotencia, qu\xe9 errores son retryables)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': El libro "Microservices Patterns" (Chris Richardson, 2018) y "Building Microservices" (Sam Newman, 2021) discuten esto. Netflix Hystrix (ahora Resilience4j) implementaba retries/circuit breakers en la aplicaci\xf3n. Istio/Envoy y Dapr los implementan en la plataforma. La tendencia es mover resiliencia a la plataforma (porque la app no deber\xeda preocuparse de "c\xf3mo" llamar a otro servicio, solo de "qu\xe9" l\xf3gica de negocio ejecutar).']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"10-cuestionar-es-el-12-factor-app-todav\xeda-relevante-en-2025-o-necesita-una-actualizaci\xf3n-significativa-para-la-era-de-serverless-webassembly-y-edge-computing",children:'10. [Cuestionar] \xbfEs el "12 Factor App" todav\xeda relevante en 2025 o necesita una actualizaci\xf3n significativa para la era de serverless, WebAssembly, y edge computing?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Los 12 factores originales (2012) son sorprendentemente vigentes: externalizar configuraci\xf3n, stateless processes, backing services como recursos, dev/prod parity \u2014 todos siguen siendo fundamentales. Pero hay vac\xedos: 1) Observabilidad (logs, metrics, traces): en 2012 se asum\xeda que los logs eran solo stdout. Hoy necesitamos structured logs, traces distribuidas, y m\xe9tricas de aplicaci\xf3n. 2) Seguridad: los 12 factores no mencionan identidad de servicio, mTLS, secretos din\xe1micos, o supply chain security. 3) Stateful workloads: los 12 factores asumen stateless, pero hoy los operadores de BD en K8s permiten stateful de manera cloud-native. 4) Serverless/event-driven: los 12 factores asumen HTTP request-response. Hoy hay sistemas event-driven (Kafka, Pub/Sub) y funciones serverless. 5) Multi-cloud/edge: portabilidad entre clouds y edge locations no era un factor en 2012. Kevin Hoffman (Beyond the 12 Factor, 2016) y Cornelia Davis (Cloud Native Patterns, 2019) extienden los factores. La comunidad open-source (CNCF) est\xe1 trabajando en una actualizaci\xf3n (Cloud Native Principles)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Adam Wiggins (co-autor) dijo en 2020 que los 12 factores necesitan actualizaci\xf3n pero los principios core son atemporales. La CNCF TAG App Delivery est\xe1 trabajando en "Cloud Native Application Principles" (draft en github.com/cncf/tag-app-delivery). Para 2025, los 12 factores + Beyond + Cloud Native Principles juntos forman una gu\xeda completa.']})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>c});var s=o(96540);const n={},r=s.createContext(n);function i(e){const a=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),s.createElement(r.Provider,{value:a},e.children)}}}]);